  /**
   * @method
   * @name coinbase#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/time
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/public/get-server-time
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.method] 'v2PublicGetTime' or
   * 'v3PublicGetBrokerageTime' default is 'v2PublicGetTime'
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<ccxt::any>
  fetchTime(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any defaultMethod =
                     this->safeString(this->options, std::string("fetchTime"),
                                      std::string("v2PublicGetTime"));
                 ccxt::any method = this->safeString(
                     params, std::string("method"), defaultMethod);
                 params = this->omit(params, std::string("method"));
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(method, std::string("v2PublicGetTime")))) {
                   response = awaitValue(this->v2PublicGetTime(params));
                   //
                   //     {
                   //         "data": {
                   //             "epoch": 1589295679,
                   //             "iso": "2020-05-12T15:01:19Z"
                   //         }
                   //     }
                   //
                   response = this->safeDict(response, std::string("data"),
                                             ccxt::dict{});
                 } else {
                   response =
                       awaitValue(this->v3PublicGetBrokerageTime(params));
                 }
                 return this->safeTimestamp2(response, std::string("epoch"),
                                             std::string("epochSeconds"));
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchAccounts
   * @description fetch all the accounts associated with a profile
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/accounts/list-accounts
   * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/accounts
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object} a dictionary of [account structures]{@link
   * https://docs.ccxt.com/?id=account-structure} indexed by the account type
   */
  std::shared_future<ccxt::any>
  fetchAccounts(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any method = this->safeString(
                     this->options, std::string("fetchAccounts"),
                     std::string("fetchAccountsV3"));
                 if (isTrue(isEqual(method, std::string("fetchAccountsV3")))) {
                   return awaitValue(this->fetchAccountsV3(params));
                 }
                 return awaitValue(this->fetchAccountsV2(params));
               })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  fetchAccountsV2(ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchAccounts"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchAccounts"), ccxt::any{}, ccxt::any{},
                       ccxt::any{}, params, std::string("next_starting_after"),
                       std::string("starting_after"), ccxt::any{}, 100));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("limit"), 100},
                 };
                 ccxt::any response = awaitValue(
                     this->v2PrivateGetAccounts(this->extend(request, params)));
                 //
                 //     {
                 //         "pagination": {
                 //             "ending_before": null,
                 //             "starting_after": null,
                 //             "previous_ending_before": null,
                 //             "next_starting_after": null,
                 //             "limit": 244,
                 //             "order": "desc",
                 //             "previous_uri": null,
                 //             "next_uri": null
                 //         },
                 //         "data": [
                 //             {
                 //                 "id": "XLM",
                 //                 "name": "XLM Wallet",
                 //                 "primary": false,
                 //                 "type": "wallet",
                 //                 "currency": {
                 //                     "code": "XLM",
                 //                     "name": "Stellar Lumens",
                 //                     "color": "#000000",
                 //                     "sort_index": 127,
                 //                     "exponent": 7,
                 //                     "type": "crypto",
                 //                     "address_regex": "^G[A-Z2-7]{55}$",
                 //                     "asset_id":
                 //                     "13b83335-5ede-595b-821e-5bcdfa80560f",
                 //                     "destination_tag_name": "XLM Memo ID",
                 //                     "destination_tag_regex": "^[ -~]{1,28}$"
                 //                 },
                 //                 "balance": {
                 //                     "amount": "0.0000000",
                 //                     "currency": "XLM"
                 //                 },
                 //                 "created_at": null,
                 //                 "updated_at": null,
                 //                 "resource": "account",
                 //                 "resource_path": "/v2/accounts/XLM",
                 //                 "allow_deposits": true,
                 //                 "allow_withdrawals": true
                 //             },
                 //         ]
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 ccxt::any pagination = this->safeDict(
                     response, std::string("pagination"), ccxt::dict{});
                 ccxt::any cursor = this->safeString(
                     pagination, std::string("next_starting_after"));
                 ccxt::any accounts = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 ccxt::any length = getArrayLength(accounts);
                 ccxt::any lastIndex = subtract(length, 1);
                 ccxt::any last =
                     this->safeDict(accounts, lastIndex, ccxt::dict{});
                 if (isTrue(isTrue((!isEqual(cursor, ccxt::any{}))) &&
                            isTrue((!isEqual(cursor, std::string("")))))) {
                   ::setValue(last, std::string("next_starting_after"), cursor);
                   ::setValue(accounts, lastIndex, last);
                 }
                 return this->parseAccounts(data, params);
               })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  fetchAccountsV3(ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchAccounts"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchAccounts"), ccxt::any{}, ccxt::any{},
                       ccxt::any{}, params, std::string("cursor"),
                       std::string("cursor"), ccxt::any{}, 250));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("limit"), 250},
                 };
                 ccxt::any response =
                     awaitValue(this->v3PrivateGetBrokerageAccounts(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "accounts": [
                 //             {
                 //                 "uuid":
                 //                 "11111111-1111-1111-1111-111111111111",
                 //                 "name": "USDC Wallet",
                 //                 "currency": "USDC",
                 //                 "available_balance": {
                 //                     "value": "0.0000000000000000",
                 //                     "currency": "USDC"
                 //                 },
                 //                 "default": true,
                 //                 "active": true,
                 //                 "created_at": "2023-01-04T06:20:06.456Z",
                 //                 "updated_at": "2023-01-04T06:20:07.181Z",
                 //                 "deleted_at": null,
                 //                 "type": "ACCOUNT_TYPE_CRYPTO",
                 //                 "ready": false,
                 //                 "hold": {
                 //                     "value": "0.0000000000000000",
                 //                     "currency": "USDC"
                 //                 }
                 //             },
                 //             ...
                 //         ],
                 //         "has_next": false,
                 //         "cursor": "",
                 //         "size": 9
                 //     }
                 //
                 ccxt::any accounts = this->safeList(
                     response, std::string("accounts"), ccxt::list{});
                 ccxt::any accountsLength = getArrayLength(accounts);
                 ccxt::any cursor =
                     this->safeString(response, std::string("cursor"));
                 if (isTrue(isTrue(isTrue((isGreaterThan(accountsLength, 0))) &&
                                   isTrue((!isEqual(cursor, ccxt::any{})))) &&
                            isTrue((!isEqual(cursor, std::string("")))))) {
                   ccxt::any lastIndex = subtract(accountsLength, 1);
                   ccxt::any last =
                       this->safeDict(accounts, lastIndex, ccxt::dict{});
                   ::setValue(last, std::string("cursor"), cursor);
                   ::setValue(accounts, lastIndex, last);
                 }
                 return this->parseAccounts(accounts, params);
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchPortfolios
   * @description fetch all the portfolios
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/portfolios/list-portfolios
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [account structures]{@link
   * https://docs.ccxt.com/?id=account-structure} indexed by the account type
   */
  virtual std::shared_future<ccxt::any>
  fetchPortfolios(ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any response =
                     awaitValue(this->v3PrivateGetBrokeragePortfolios(params));
                 ccxt::any portfolios = this->safeList(
                     response, std::string("portfolios"), ccxt::list{});
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any i = 0;
                      isLessThan(i, getArrayLength(portfolios));
                      postFixIncrement(i)) {
                   ccxt::any portfolio = ::getValue(portfolios, i);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"),
                            this->safeString(portfolio, std::string("uuid"))},
                           {std::string("type"),
                            this->safeString(portfolio, std::string("type"))},
                           {std::string("code"), ccxt::any{}},
                           {std::string("info"), portfolio},
                       });
                 }
                 return result;
               })
        .share();
  }

  ccxt::any parseAccount(ccxt::any account) override {
    //
    // fetchAccountsV2
    //
    //     {
    //         "id": "XLM",
    //         "name": "XLM Wallet",
    //         "primary": false,
    //         "type": "wallet",
    //         "currency": {
    //             "code": "XLM",
    //             "name": "Stellar Lumens",
    //             "color": "#000000",
    //             "sort_index": 127,
    //             "exponent": 7,
    //             "type": "crypto",
    //             "address_regex": "^G[A-Z2-7]{55}$",
    //             "asset_id": "13b83335-5ede-595b-821e-5bcdfa80560f",
    //             "destination_tag_name": "XLM Memo ID",
    //             "destination_tag_regex": "^[ -~]{1,28}$"
    //         },
    //         "balance": {
    //             "amount": "0.0000000",
    //             "currency": "XLM"
    //         },
    //         "created_at": null,
    //         "updated_at": null,
    //         "resource": "account",
    //         "resource_path": "/v2/accounts/XLM",
    //         "allow_deposits": true,
    //         "allow_withdrawals": true
    //     }
    //
    // fetchAccountsV3
    //
    //     {
    //         "uuid": "11111111-1111-1111-1111-111111111111",
    //         "name": "USDC Wallet",
    //         "currency": "USDC",
    //         "available_balance": {
    //             "value": "0.0000000000000000",
    //             "currency": "USDC"
    //         },
    //         "default": true,
    //         "active": true,
    //         "created_at": "2023-01-04T06:20:06.456Z",
    //         "updated_at": "2023-01-04T06:20:07.181Z",
    //         "deleted_at": null,
    //         "type": "ACCOUNT_TYPE_CRYPTO",
    //         "ready": false,
    //         "hold": {
    //             "value": "0.0000000000000000",
    //             "currency": "USDC"
    //         }
    //     }
    //
    ccxt::any active = this->safeBool(account, std::string("active"));
    ccxt::any currencyIdV3 = this->safeString(account, std::string("currency"));
    ccxt::any currency =
        this->safeDict(account, std::string("currency"), ccxt::dict{});
    ccxt::any currencyId =
        this->safeString(currency, std::string("code"), currencyIdV3);
    ccxt::any typeV3 = this->safeString(account, std::string("name"));
    ccxt::any typeV2 = this->safeString(account, std::string("type"));
    ccxt::any parts = split(typeV3, std::string(" "));
    return ccxt::dict{
        {std::string("id"),
         this->safeString2(account, std::string("id"), std::string("uuid"))},
        {std::string("type"), (isTrue((!isEqual(active, ccxt::any{})))
                                   ? ccxt::any(this->safeStringLower(parts, 1))
                                   : ccxt::any(typeV2))},
        {std::string("code"), this->safeCurrencyCode(currencyId)},
        {std::string("info"), account},
    };
  }

  /**
   * @method
   * @name coinbase#createDepositAddress
   * @description create a currency deposit address
   * @see
   * https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/onchain-addresses
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<ccxt::any>
  createDepositAddress(ccxt::any code,
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any accountId =
                     this->safeString(params, std::string("account_id"));
                 params = this->omit(params, std::string("account_id"));
                 if (isTrue(isEqual(accountId, ccxt::any{}))) {
                   awaitValue(this->loadAccounts());
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(this->accounts));
                        postFixIncrement(i)) {
                     ccxt::any account = ::getValue(this->accounts, i);
                     if (isTrue(isTrue(isEqual(
                                    ::getValue(account, std::string("code")),
                                    code)) &&
                                isTrue(isEqual(
                                    ::getValue(account, std::string("type")),
                                    std::string("wallet"))))) {
                       accountId = ::getValue(account, std::string("id"));
                       break;
                     }
                   }
                 }
                 if (isTrue(isEqual(accountId, ccxt::any{}))) {
                   throw ExchangeError(toString(add(
                       add(add(this->id,
                               std::string(
                                   " createDepositAddress() could not find the "
                                   "account with matching currency code ")),
                           code),
                       std::string(", specify an `account_id` extra param to "
                                   "target specific wallet"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("account_id"), accountId},
                 };
                 ccxt::any response =
                     awaitValue(this->v2PrivatePostAccountsAccountIdAddresses(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "data": {
                 //             "id": "05b1ebbf-9438-5dd4-b297-2ddedc98d0e4",
                 //             "address": "coinbasebase",
                 //             "address_info": {
                 //                 "address": "coinbasebase",
                 //                 "destination_tag": "287594668"
                 //             },
                 //             "name": null,
                 //             "created_at": "2019-07-01T14:39:29Z",
                 //             "updated_at": "2019-07-01T14:39:29Z",
                 //             "network": "eosio",
                 //             "uri_scheme": "eosio",
                 //             "resource": "address",
                 //             "resource_path":
                 //             "/v2/accounts/14cfc769-e852-52f3-b831-711c104d194c/addresses/05b1ebbf-9438-5dd4-b297-2ddedc98d0e4",
                 //             "warnings": [
                 //                 {
                 //                     "title": "Only send EOS (EOS) to this
                 //                     address", "details": "Sending any other
                 //                     cryptocurrency will result in permanent
                 //                     loss.", "image_url":
                 //                     "https://dynamic-assets.coinbase.com/deaca3d47b10ed4a91a872e9618706eec34081127762d88f2476ac8e99ada4b48525a9565cf2206d18c04053f278f693434af4d4629ca084a9d01b7a286a7e26/asset_icons/1f8489bb280fb0a0fd643c1161312ba49655040e9aaaced5f9ad3eeaf868eadc.png"
                 //                 },
                 //                 {
                 //                     "title": "Both an address and EOS memo
                 //                     are required to receive EOS", "details":
                 //                     "If you send funds without an EOS memo
                 //                     or with an incorrect EOS memo, your
                 //                     funds cannot be credited to your
                 //                     account.", "image_url":
                 //                     "https://www.coinbase.com/assets/receive-warning-2f3269d83547a7748fb39d6e0c1c393aee26669bfea6b9f12718094a1abff155.png"
                 //                 }
                 //             ],
                 //             "warning_title": "Only send EOS (EOS) to this
                 //             address", "warning_details": "Sending any other
                 //             cryptocurrency will result in permanent loss.",
                 //             "destination_tag": "287594668",
                 //             "deposit_uri":
                 //             "eosio:coinbasebase?dt=287594668",
                 //             "callback_url": null
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any tag =
                     this->safeString(data, std::string("destination_tag"));
                 ccxt::any address =
                     this->safeString(data, std::string("address"));
                 return ccxt::dict{
                     {std::string("currency"), code},
                     {std::string("tag"), tag},
                     {std::string("address"), address},
                     {std::string("network"), ccxt::any{}},
                     {std::string("info"), response},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchMySells
   * @ignore
   * @description fetch sells
   * @see
   * https://docs.cdp.coinbase.com/coinbase-app/oauth2-integration/available-apis
   * @param {string} symbol not used by fetchMySells ()
   * @param {int} [since] timestamp in ms of the earliest sell, default is
   * undefined
   * @param {int} [limit] max number of sells to return, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [list of order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchMySells(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
               ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // v2 did't have an endpoint for all historical trades
                 ccxt::any request = this->prepareAccountRequest(limit, params);
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any query =
                     this->omit(params, ccxt::list{std::string("account_id"),
                                                   std::string("accountId")});
                 ccxt::any sells =
                     awaitValue(this->v2PrivateGetAccountsAccountIdSells(
                         this->extend(request, query)));
                 ccxt::any sellsData =
                     this->safeList(sells, std::string("data"), ccxt::list{});
                 return this->parseTrades(sellsData, ccxt::any{}, since, limit);
               })
        .share();
  }

