  /**
   * @method
   * @name coinbase#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/orders/list-orders
   * @param {string} symbol unified market symbol that the orders were made in
   * @param {int} [since] the earliest time in ms to fetch orders
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = 100, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchOrders"), symbol, since, limit, params,
                       std::string("cursor"), std::string("cursor"),
                       ccxt::any{}, 1000));
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(market, ccxt::any{}))) {
                   ::setValue(request, std::string("product_id"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_date"),
                              this->iso8601(since));
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("end_date"),
                              this->iso8601(until));
                 }
                 ccxt::any response = awaitValue(
                     this->v3PrivateGetBrokerageOrdersHistoricalBatch(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "orders": [
                 //             {
                 //                 "order_id":
                 //                 "813a53c5-3e39-47bb-863d-2faf685d22d8",
                 //                 "product_id": "BTC-USDT",
                 //                 "user_id":
                 //                 "1111111-1111-1111-1111-111111111111",
                 //                 "order_configuration": {
                 //                     "market_market_ioc": {
                 //                         "quote_size": "6.36"
                 //                     }
                 //                 },
                 //                 "side": "BUY",
                 //                 "client_order_id":
                 //                 "18eb9947-db49-4874-8e7b-39b8fe5f4317",
                 //                 "status": "FILLED",
                 //                 "time_in_force": "IMMEDIATE_OR_CANCEL",
                 //                 "created_time":
                 //                 "2023-01-18T01:37:37.975552Z",
                 //                 "completion_percentage": "100",
                 //                 "filled_size": "0.000297920684505",
                 //                 "average_filled_price":
                 //                 "21220.6399999973697697", "fee": "",
                 //                 "number_of_fills": "2",
                 //                 "filled_value": "6.3220675944333996",
                 //                 "pending_cancel": false,
                 //                 "size_in_quote": true,
                 //                 "total_fees": "0.0379324055666004",
                 //                 "size_inclusive_of_fees": true,
                 //                 "total_value_after_fees": "6.36",
                 //                 "trigger_status": "INVALID_ORDER_TYPE",
                 //                 "order_type": "MARKET",
                 //                 "reject_reason":
                 //                 "REJECT_REASON_UNSPECIFIED", "settled":
                 //                 true, "product_type": "SPOT",
                 //                 "reject_message": "",
                 //                 "cancel_message": "Internal error"
                 //             },
                 //         ],
                 //         "sequence": "0",
                 //         "has_next": false,
                 //         "cursor": ""
                 //     }
                 //
                 ccxt::any orders = this->safeList(
                     response, std::string("orders"), ccxt::list{});
                 ccxt::any first = this->safeDict(orders, 0, ccxt::dict{});
                 ccxt::any cursor =
                     this->safeString(response, std::string("cursor"));
                 if (isTrue(isTrue((!isEqual(cursor, ccxt::any{}))) &&
                            isTrue((!isEqual(cursor, std::string("")))))) {
                   ::setValue(first, std::string("cursor"), cursor);
                   ::setValue(orders, 0, first);
                 }
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

