  /**
   * @method
   * @name coinbase#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/products/get-product-candles
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/public/get-public-product-candles
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch, not used by
   * coinbase
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @param {boolean} [params.usePrivate] default false, when true will use the
   * private endpoint to fetch the candles
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any maxLimit = 300;
                 limit = (isTrue((isEqual(limit, ccxt::any{})))
                              ? ccxt::any(maxLimit)
                              : ccxt::any(mathMin(limit, maxLimit)));
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("paginate"),
                     false);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, subtract(maxLimit, 1)));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("product_id"),
                      ::getValue(market, std::string("id"))},
                     {std::string("granularity"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 ccxt::any until = this->safeInteger2(
                     params, std::string("until"), std::string("end"));
                 params = this->omit(params, ccxt::list{std::string("until")});
                 ccxt::any duration = this->parseTimeframe(timeframe);
                 ccxt::any requestedDuration = multiply(limit, duration);
                 ccxt::any sinceString = ccxt::any{};
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   sinceString = this->numberToString(
                       this->parseToInt(divide(since, 1000)));
                 } else {
                   ccxt::any now = toString(this->seconds());
                   sinceString = ccxt::Precise::stringSub(
                       now, toString(requestedDuration));
                 }
                 ::setValue(request, std::string("start"), sinceString);
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("end"),
                              this->numberToString(
                                  this->parseToInt(divide(until, 1000))));
                 } else {
                   // 300 candles max
                   ::setValue(request, std::string("end"),
                              ccxt::Precise::stringAdd(
                                  sinceString, toString(requestedDuration)));
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any usePrivate = false;
                 ccxt::any usePrivateparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchOHLCV"),
                         std::string("usePrivate"), false);
                 usePrivate = ::getValue(usePrivateparamsVariable, 0);
                 params = ::getValue(usePrivateparamsVariable, 1);
                 if (isTrue(usePrivate)) {
                   response = awaitValue(
                       this->v3PrivateGetBrokerageProductsProductIdCandles(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->v3PublicGetBrokerageMarketProductsProductIdCandles(
                           this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "candles": [
                 //             {
                 //                 "start": "1673391780",
                 //                 "low": "17414.36",
                 //                 "high": "17417.99",
                 //                 "open": "17417.74",
                 //                 "close": "17417.38",
                 //                 "volume": "1.87780853"
                 //             },
                 //         ]
                 //     }
                 //
                 ccxt::any candles = this->safeList(
                     response, std::string("candles"), ccxt::list{});
                 return this->parseOHLCVs(candles, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     [
    //         {
    //             "start": "1673391780",
    //             "low": "17414.36",
    //             "high": "17417.99",
    //             "open": "17417.74",
    //             "close": "17417.38",
    //             "volume": "1.87780853"
    //         },
    //     ]
    //
    return ccxt::list{this->safeTimestamp(ohlcv, std::string("start")),
                      this->safeNumber(ohlcv, std::string("open")),
                      this->safeNumber(ohlcv, std::string("high")),
                      this->safeNumber(ohlcv, std::string("low")),
                      this->safeNumber(ohlcv, std::string("close")),
                      this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name coinbase#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/products/get-market-trades
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/public/get-public-market-trades
   * @param {string} symbol unified market symbol of the trades
   * @param {int} [since] not used by coinbase fetchTrades
   * @param {int} [limit] the maximum number of trade structures to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.usePrivate] default false, when true will use the
   * private endpoint to fetch the trades
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("product_id"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start"),
                              this->numberToString(
                                  this->parseToInt(divide(since, 1000))));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 ccxt::any until = ccxt::any{};
                 ccxt::any untilparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchTrades"), std::string("until"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("end"),
                              this->numberToString(
                                  this->parseToInt(divide(until, 1000))));
                 } else if (isTrue(!isEqual(since, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchTrades() requires a `until` parameter "
                               "when you use `since` argument"))));
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any usePrivate = false;
                 ccxt::any usePrivateparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchTrades"),
                         std::string("usePrivate"), false);
                 usePrivate = ::getValue(usePrivateparamsVariable, 0);
                 params = ::getValue(usePrivateparamsVariable, 1);
                 if (isTrue(usePrivate)) {
                   response = awaitValue(
                       this->v3PrivateGetBrokerageProductsProductIdTicker(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->v3PublicGetBrokerageMarketProductsProductIdTicker(
                           this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "trades": [
                 //             {
                 //                 "trade_id": "10092327",
                 //                 "product_id": "BTC-USDT",
                 //                 "price": "17488.12",
                 //                 "size": "0.0000623",
                 //                 "time": "2023-01-11T00:52:37.557001Z",
                 //                 "side": "BUY",
                 //                 "bid": "",
                 //                 "ask": ""
                 //             },
                 //         ]
                 //     }
                 //
                 ccxt::any trades = this->safeList(
                     response, std::string("trades"), ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/orders/list-fills
   * @param {string} symbol unified market symbol of the trades
   * @param {int} [since] timestamp in ms of the earliest order, default is
   * undefined
   * @param {int} [limit] the maximum number of trade structures to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, std::string("cursor"), std::string("cursor"),
                       ccxt::any{}, 250));
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(market, ccxt::any{}))) {
                   ::setValue(request, std::string("product_id"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_sequence_timestamp"),
                              this->iso8601(since));
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("end_sequence_timestamp"),
                              this->iso8601(until));
                 }
                 ccxt::any response = awaitValue(
                     this->v3PrivateGetBrokerageOrdersHistoricalFills(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "fills": [
                 //             {
                 //                 "entry_id":
                 //                 "b88b82cc89e326a2778874795102cbafd08dd979a2a7a3c69603fc4c23c2e010",
                 //                 "trade_id":
                 //                 "cdc39e45-bbd3-44ec-bf02-61742dfb16a1",
                 //                 "order_id":
                 //                 "813a53c5-3e39-47bb-863d-2faf685d22d8",
                 //                 "trade_time":
                 //                 "2023-01-18T01:37:38.091377090Z",
                 //                 "trade_type": "FILL",
                 //                 "price": "21220.64",
                 //                 "size": "0.0046830664333996",
                 //                 "commission": "0.0000280983986004",
                 //                 "product_id": "BTC-USDT",
                 //                 "sequence_timestamp":
                 //                 "2023-01-18T01:37:38.092520Z",
                 //                 "liquidity_indicator":
                 //                 "UNKNOWN_LIQUIDITY_INDICATOR",
                 //                 "size_in_quote": true,
                 //                 "user_id":
                 //                 "1111111-1111-1111-1111-111111111111",
                 //                 "side": "BUY"
                 //             },
                 //         ],
                 //         "cursor": ""
                 //     }
                 //
                 ccxt::any trades = this->safeList(
                     response, std::string("fills"), ccxt::list{});
                 ccxt::any first = this->safeDict(trades, 0, ccxt::dict{});
                 ccxt::any cursor =
                     this->safeString(response, std::string("cursor"));
                 if (isTrue(isTrue((!isEqual(cursor, ccxt::any{}))) &&
                            isTrue((!isEqual(cursor, std::string("")))))) {
                   ::setValue(first, std::string("cursor"), cursor);
                   ::setValue(trades, 0, first);
                 }
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/products/get-product-book
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/public/get-public-product-book
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.usePrivate] default false, when true will use the
   * private endpoint to fetch the order book
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("product_id"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any usePrivate = false;
                 ccxt::any usePrivateparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchOrderBook"),
                         std::string("usePrivate"), false);
                 usePrivate = ::getValue(usePrivateparamsVariable, 0);
                 params = ::getValue(usePrivateparamsVariable, 1);
                 if (isTrue(usePrivate)) {
                   response = awaitValue(this->v3PrivateGetBrokerageProductBook(
                       this->extend(request, params)));
                 } else {
                   response =
                       awaitValue(this->v3PublicGetBrokerageMarketProductBook(
                           this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "pricebook": {
                 //             "product_id": "BTC-USDT",
                 //             "bids": [
                 //                 {
                 //                     "price": "30757.85",
                 //                     "size": "0.115"
                 //                 },
                 //             ],
                 //             "asks": [
                 //                 {
                 //                     "price": "30759.07",
                 //                     "size": "0.04877659"
                 //                 },
                 //             ],
                 //             "time": "2023-06-30T04:02:40.533606Z"
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(
                     response, std::string("pricebook"), ccxt::dict{});
                 ccxt::any time = this->safeString(data, std::string("time"));
                 ccxt::any timestamp = this->parse8601(time);
                 return this->parseOrderBook(
                     data, symbol, timestamp, std::string("bids"),
                     std::string("asks"), std::string("price"),
                     std::string("size"));
               })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchBidsAsks
   * @description fetches the bid and ask price and volume for multiple markets
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/products/get-best-bid-ask
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * bids and asks for, all markets are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchBidsAsks(ccxt::any symbols = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols);
                        ccxt::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                          ::setValue(request, std::string("product_ids"),
                                     this->marketIds(symbols));
                        }
                        ccxt::any response =
                            awaitValue(this->v3PrivateGetBrokerageBestBidAsk(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "pricebooks": [
                        //             {
                        //                 "product_id": "TRAC-EUR",
                        //                 "bids": [
                        //                     {
                        //                         "price": "0.2384",
                        //                         "size": "386.1"
                        //                     }
                        //                 ],
                        //                 "asks": [
                        //                     {
                        //                         "price": "0.2406",
                        //                         "size": "672"
                        //                     }
                        //                 ],
                        //                 "time": "2023-06-30T07:15:24.656044Z"
                        //             },
                        //         ]
                        //     }
                        //
                        ccxt::any tickers = this->safeList(
                            response, std::string("pricebooks"), ccxt::list{});
                        return this->parseTickers(tickers, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name coinbase#withdraw
   * @description make a withdrawal
   * @see https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/send-crypto
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} [tag] an optional tag for the withdrawal
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] the cryptocurrency network to use for the
   * withdrawal using the lowercase name like bitcoin, ethereum, solana, etc.
   * @param {object} [params.travel_rule_data] some regions require travel rule
   * information for crypto withdrawals, see the exchange docs for details
   * https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/travel-rule
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  withdraw(ccxt::any code, ccxt::any amount, ccxt::any address,
           ccxt::any tag = ccxt::any{},
           ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                ccxt::any tagparamsVariable =
                    this->handleWithdrawTagAndParams(tag, params);
                tag = ::getValue(tagparamsVariable, 0);
                params = ::getValue(tagparamsVariable, 1);
                this->checkAddress(address);
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any currency = this->currency(code);
                ccxt::any request = ccxt::dict{
                    {std::string("type"), std::string("send")},
                    {std::string("to"), address},
                    {std::string("amount"), this->numberToString(amount)},
                    {std::string("currency"),
                     ::getValue(currency, std::string("id"))},
                };
                ccxt::any accountId =
                    this->safeString2(params, std::string("account_id"),
                                      std::string("accountId"));
                params =
                    this->omit(params, ccxt::list{std::string("account_id"),
                                                  std::string("accountId")});
                if (isTrue(isEqual(accountId, ccxt::any{}))) {
                  if (isTrue(isEqual(code, ccxt::any{}))) {
                    throw ArgumentsRequired(toString(add(
                        this->id,
                        std::string(
                            " withdraw() requires an account_id (or accountId) "
                            "parameter OR a currency code argument"))));
                  }
                  accountId = awaitValue(this->findAccountId(code, params));
                  if (isTrue(isEqual(accountId, ccxt::any{}))) {
                    throw ExchangeError(toString(add(
                        add(this->id,
                            std::string(
                                " withdraw() could not find account id for ")),
                        code)));
                  }
                  ::setValue(request, std::string("account_id"), accountId);
                } else {
                  ::setValue(request, std::string("account_id"), accountId);
                }
                if (isTrue(!isEqual(tag, ccxt::any{}))) {
                  ::setValue(request, std::string("destination_tag"), tag);
                }
                ccxt::any response =
                    awaitValue(this->v2PrivatePostAccountsAccountIdTransactions(
                        this->extend(request, params)));
                //
                //     {
                //         "data": {
                //             "id": "a1794ecf-5693-55fa-70cf-ef731748ed82",
                //             "type": "send",
                //             "status": "pending",
                //             "amount": {
                //                 "amount": "-14.008308",
                //                 "currency": "USDC"
                //             },
                //             "native_amount": {
                //                 "amount": "-18.74",
                //                 "currency": "CAD"
                //             },
                //             "description": null,
                //             "created_at": "2024-01-12T01:27:31Z",
                //             "updated_at": "2024-01-12T01:27:31Z",
                //             "resource": "transaction",
                //             "resource_path":
                //             "/v2/accounts/a34bgfad-ed67-538b-bffc-730c98c10da0/transactions/a1794ecf-5693-55fa-70cf-ef731748ed82",
                //             "instant_exchange": false,
                //             "network": {
                //                 "status": "pending",
                //                 "status_description": "Pending (est. less
                //                 than 10 minutes)", "transaction_fee": {
                //                     "amount": "4.008308",
                //                     "currency": "USDC"
                //                 },
                //                 "transaction_amount": {
                //                     "amount": "10.000000",
                //                     "currency": "USDC"
                //                 },
                //                 "confirmations": 0
                //             },
                //             "to": {
                //                 "resource": "ethereum_address",
                //                 "address": "0x9...",
                //                 "currency": "USDC",
                //                 "address_info": {
                //                     "address": "0x9..."
                //                 }
                //             },
                //             "idem": "748d8591-dg9a-7831-a45b-crd61dg78762",
                //             "details": {
                //                 "title": "Sent USDC",
                //                 "subtitle": "To USDC address on Ethereum
                //                 network", "header": "Sent 14.008308 USDC
                //                 ($18.74)", "health": "warning"
                //             },
                //             "hide_native_amount": false
                //         }
                //     }
                //
                ccxt::any data =
                    this->safeDict(response, std::string("data"), ccxt::dict{});
                return this->parseTransaction(data, currency);
              })
            .share();
  }

