  ccxt::any parseDepositAddress(ccxt::any depositAddress,
                                ccxt::any currency = ccxt::any{}) override {
    //
    //    {
    //        id: '64ceb5f1-5fa2-5310-a4ff-9fd46271003d',
    //        address: '5xjPKeAXpnhA2kHyinvdVeui6RXVdEa3B2J3SCAwiKnk',
    //        address_info: {
    //            address:
    //            'GCF74576I7AQ56SLMKBQAP255EGUOWCRVII3S44KEXVNJEOIFVBDMXVL',
    //            destination_tag: '3722061866'
    //        },
    //        name: null,
    //        created_at: '2023-05-29T21:12:12Z',
    //        updated_at: '2023-05-29T21:12:12Z',
    //        network: 'solana',
    //        uri_scheme: 'solana',
    //        resource: 'address',
    //        resource_path:
    //        '/v2/accounts/a7b3d387-bfb8-5ce7-b8da-1f507e81cf25/addresses/64ceb5f1-5fa2-5310-a4ff-9fd46271003d',
    //        warnings: [
    //            {
    //            type: 'correct_address_warning',
    //            title: 'This is an ERC20 USDC address.',
    //            details: 'Only send ERC20 USD Coin (USDC) to this address.',
    //            image_url:
    //            'https://www.coinbase.com/assets/addresses/global-receive-warning-a3d91807e61c717e5a38d270965003dcc025ca8a3cea40ec3d7835b7c86087fa.png',
    //            options: [ { text: 'I understand', style: 'primary', id:
    //            'dismiss' } ]
    //            }
    //        ],
    //        qr_code_image_url:
    //        'https://static-assets.coinbase.com/p2p/l2/asset_network_combinations/v5/usdc-solana.png',
    //        address_label: 'USDC address (Solana)',
    //        default_receive: true,
    //        deposit_uri:
    //        'solana:5xjPKeAXpnhA2kHyinvdVeui6RXVdEa3B2J3SCAwiKnk?spl-token=EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v',
    //        callback_url: null,
    //        share_address_copy: {
    //            line1: '5xjPKeAXpnhA2kHyinvdVeui6RXVdEa3B2J3SCAwiKnk',
    //            line2: 'This address can only receive USDC-SPL from Solana
    //            network. Don’t send USDC from other networks, other SPL tokens
    //            or NFTs, or it may result in a loss of funds.'
    //        },
    //        receive_subtitle: 'ERC-20',
    //        inline_warning: {
    //            text: 'This address can only receive USDC-SPL from Solana
    //            network. Don’t send USDC from other networks, other SPL tokens
    //            or NFTs, or it may result in a loss of funds.', tooltip: {
    //            title: 'USDC (Solana)',
    //            subtitle: 'This address can only receive USDC-SPL from Solana
    //            network.'
    //            }
    //        }
    //    }
    //
    // {
    //     "id":"3f2434234943-8c1c-50ef-a5a1-342213bbf45d",
    //     "address":"0x123123126F5921XXXXX",
    //     "currency":"USDC",
    //     "name":"",
    //     "network":"ethereum",
    //     "created_at":"2022-03-17T09:20:17.002Z",
    //     "updated_at":"2022-03-17T09:20:17.002Z",
    //     "resource":"addresses",
    //     "resource_path":"v2/accounts/b1091c6e-9ef2-5e4d-b352-665d0cf8f742/addresses/32fd0943-8c1c-50ef-a5a1-342213bbf45d",
    //     "destination_tag":""
    // }
    //
    ccxt::any address =
        this->safeString(depositAddress, std::string("address"));
    this->checkAddress(address);
    ccxt::any networkId =
        this->safeString(depositAddress, std::string("network"));
    ccxt::any code = this->safeCurrencyCode(ccxt::any{}, currency);
    ccxt::any addressLabel =
        this->safeString(depositAddress, std::string("address_label"));
    ccxt::any currencyId = ccxt::any{};
    if (isTrue(!isEqual(addressLabel, ccxt::any{}))) {
      ccxt::any splitAddressLabel = split(addressLabel, std::string(" "));
      currencyId = this->safeString(splitAddressLabel, 0);
    } else {
      currencyId = this->safeString(depositAddress, std::string("currency"));
    }
    ccxt::any addressInfo =
        this->safeDict(depositAddress, std::string("address_info"));
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("network"), this->networkIdToCode(networkId, code)},
        {std::string("address"), address},
        {std::string("tag"),
         this->safeString(addressInfo, std::string("destination_tag"))},
    };
  }

  /**
   * @method
   * @name coinbase#deposit
   * @description make a deposit
   * @see https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/deposit-fiat
   * @param {string} code unified currency code
   * @param {float} amount the amount to deposit
   * @param {string} id the payment method id to be used for the deposit, can be
   * retrieved from v2PrivateGetPaymentMethods
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.accountId] the id of the account to deposit into
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  virtual std::shared_future<ccxt::any>
  deposit(ccxt::any code, ccxt::any amount, ccxt::any id,
          ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any accountId =
                     this->safeString2(params, std::string("account_id"),
                                       std::string("accountId"));
                 params =
                     this->omit(params, ccxt::list{std::string("account_id"),
                                                   std::string("accountId")});
                 if (isTrue(isEqual(accountId, ccxt::any{}))) {
                   if (isTrue(isEqual(code, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(
                             " deposit() requires an account_id (or accountId) "
                             "parameter OR a currency code argument"))));
                   }
                   accountId = awaitValue(this->findAccountId(code, params));
                   if (isTrue(isEqual(accountId, ccxt::any{}))) {
                     throw ExchangeError(toString(add(
                         add(this->id,
                             std::string(
                                 " deposit() could not find account id for ")),
                         code)));
                   }
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("account_id"), accountId},
                     {std::string("amount"), this->numberToString(amount)},
                     {std::string("currency"), toUpperCase(code)},
                     {std::string("payment_method"), id},
                     {std::string("commit"), true},
                 };
                 ccxt::any response =
                     awaitValue(this->v2PrivatePostAccountsAccountIdDeposits(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "data": {
                 //             "id": "67e0eaec-07d7-54c4-a72c-2e92826897df",
                 //             "status": "created",
                 //             "payment_method": {
                 //                 "id":
                 //                 "83562370-3e5c-51db-87da-752af5ab9559",
                 //                 "resource": "payment_method",
                 //                 "resource_path":
                 //                 "/v2/payment-methods/83562370-3e5c-51db-87da-752af5ab9559"
                 //             },
                 //             "transaction": {
                 //                 "id":
                 //                 "441b9494-b3f0-5b98-b9b0-4d82c21c252a",
                 //                 "resource": "transaction",
                 //                 "resource_path":
                 //                 "/v2/accounts/2bbf394c-193b-5b2a-9155-3b4732659ede/transactions/441b9494-b3f0-5b98-b9b0-4d82c21c252a"
                 //             },
                 //             "amount": {
                 //                 "amount": "10.00",
                 //                 "currency": "USD"
                 //             },
                 //             "subtotal": {
                 //                 "amount": "10.00",
                 //                 "currency": "USD"
                 //             },
                 //             "created_at": "2015-01-31T20:49:02Z",
                 //             "updated_at": "2015-02-11T16:54:02-08:00",
                 //             "resource": "deposit",
                 //             "resource_path":
                 //             "/v2/accounts/2bbf394c-193b-5b2a-9155-3b4732659ede/deposits/67e0eaec-07d7-54c4-a72c-2e92826897df",
                 //             "committed": true,
                 //             "fee": {
                 //                 "amount": "0.00",
                 //                 "currency": "USD"
                 //             },
                 //             "payout_at": "2015-02-18T16:54:00-08:00"
                 //         }
                 //     }
                 //
                 // https://github.com/ccxt/ccxt/issues/25484
                 ccxt::any data =
                     this->safeDict2(response, std::string("data"),
                                     std::string("transfer"), ccxt::dict{});
                 return this->parseTransaction(data);
               })
        .share();
  }

