  virtual std::shared_future<ccxt::any>
  fetchDepositMethodIds(ccxt::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->v3PrivateGetBrokeragePaymentMethods(params));
                        //
                        //     {
                        //         "payment_methods": [
                        //             {
                        //                 "id": "21b39a5d-f7b46876fb2e",
                        //                 "type": "COINBASE_FIAT_ACCOUNT",
                        //                 "name": "CAD Wallet",
                        //                 "currency": "CAD",
                        //                 "verified": true,
                        //                 "allow_buy": false,
                        //                 "allow_sell": true,
                        //                 "allow_deposit": false,
                        //                 "allow_withdraw": false,
                        //                 "created_at": "2023-06-29T19:58:46Z",
                        //                 "updated_at": "2023-10-30T20:25:01Z"
                        //             }
                        //         ]
                        //     }
                        //
                        ccxt::any result = this->safeList(
                            response, std::string("payment_methods"),
                            ccxt::list{});
                        return this->parseDepositMethodIds(result);
                      })
        .share();
  }

  /**
   * @method
   * @name coinbase#fetchDepositMethodId
   * @description fetch the deposit id for a fiat currency associated with this
   * account
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/payment-methods/get-payment-method
   * @param {string} id the deposit payment method id
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [deposit id structure]{@link
   * https://docs.ccxt.com/?id=deposit-id-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchDepositMethodId(ccxt::any id, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("payment_method_id"), id},
                 };
                 ccxt::any response = awaitValue(
                     this->v3PrivateGetBrokeragePaymentMethodsPaymentMethodId(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "payment_method": {
                 //             "id": "21b39a5d-f7b46876fb2e",
                 //             "type": "COINBASE_FIAT_ACCOUNT",
                 //             "name": "CAD Wallet",
                 //             "currency": "CAD",
                 //             "verified": true,
                 //             "allow_buy": false,
                 //             "allow_sell": true,
                 //             "allow_deposit": false,
                 //             "allow_withdraw": false,
                 //             "created_at": "2023-06-29T19:58:46Z",
                 //             "updated_at": "2023-10-30T20:25:01Z"
                 //         }
                 //     }
                 //
                 ccxt::any result = this->safeDict(
                     response, std::string("payment_method"), ccxt::dict{});
                 return this->parseDepositMethodId(result);
               })
        .share();
  }

  virtual ccxt::any parseDepositMethodIds(ccxt::any ids,
                                          ccxt::any params = ccxt::dict{}) {
    ccxt::any result = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(ids));
         postFixIncrement(i)) {
      ccxt::any id =
          this->extend(this->parseDepositMethodId(::getValue(ids, i)), params);
      arrayPush(result, id);
    }
    return result;
  }

  virtual ccxt::any parseDepositMethodId(ccxt::any depositId) {
    return ccxt::dict{
        {std::string("info"), depositId},
        {std::string("id"), this->safeString(depositId, std::string("id"))},
        {std::string("currency"),
         this->safeString(depositId, std::string("currency"))},
        {std::string("verified"),
         this->safeBool(depositId, std::string("verified"))},
        {std::string("tag"), this->safeString(depositId, std::string("name"))},
    };
  }

  /**
   * @method
   * @name coinbase#fetchConvertQuote
   * @description fetch a quote for converting from one currency to another
   * @see
   * https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/convert/create-convert-quote
   * @param {string} fromCode the currency that you want to sell and convert
   * from
   * @param {string} toCode the currency that you want to buy and convert into
   * @param {float} [amount] how much you want to trade in units of the from
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.trade_incentive_metadata] an object to fill in user
   * incentive data
   * @param {string} [params.trade_incentive_metadata.user_incentive_id] the id
   * of the incentive
   * @param {string} [params.trade_incentive_metadata.code_val] the code value
   * of the incentive
   * @returns {object} a [conversion structure]{@link
   * https://docs.ccxt.com/?id=conversion-structure}
   */
  std::shared_future<ccxt::any>
  fetchConvertQuote(ccxt::any fromCode, ccxt::any toCode,
                    ccxt::any amount = ccxt::any{},
                    ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("from_account"), fromCode},
                     {std::string("to_account"), toCode},
                     {std::string("amount"), this->numberToString(amount)},
                 };
                 ccxt::any response =
                     awaitValue(this->v3PrivatePostBrokerageConvertQuote(
                         this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("trade"),
                                                 ccxt::dict{});
                 return this->parseConversion(data);
               })
        .share();
  }

